// @FIGURE_CODE_BEGIN
/* ── Element spec (built exactly as listed) ───────────────────────────────
   axes x,y,z   -> CylinderGeometry shaft + ConeGeometry head, black #111
   xy-plane     -> PlaneGeometry patch, #e8e8e8 a=0.55 + LineLoop border #c4c4c4
   region fill  -> radial BufferGeometry disc at z=0.006, #bfe0dc a=0.45
   region edge  -> TubeGeometry along boundary curve r=0.022, #00a887
   grid         -> LineSegments (axis aligned, clipped to R), #9aa5a5
   surface      -> 56x56 BufferGeometry graph of f, MeshPhongMaterial #9ecfcb a=0.5
   patch over R -> radial BufferGeometry at z=f, #5fa9a4 a=0.6
   cylinder wall-> 1 x 128 strip BufferGeometry, #d6dbda a=0.28
   column       -> BoxGeometry(1,1,1), 6 mats: sides #f5b06a a=0.55, top #e89a48
   base rect    -> PlaneGeometry, #e89a48 a=0.85
   all columns  -> InstancedMesh(BoxGeometry) #f5b06a a=0.35
   red dots     -> SphereGeometry(0.075) #e8372a  (x2)
   dashed seg   -> Line + LineDashedMaterial #e8372a dash .12/.10
   leader arrows-> Line + ConeGeometry head, #111
──────────────────────────────────────────────────────────────────────────*/

// math (x,y,z)  ->  world (X = y, Y = z, Z = x)     [world is Y-up]
const W = (x, y, z) => new THREE.Vector3(y, z, x);

/* ── lights ───────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.88));
const dl = new THREE.DirectionalLight(0xffffff, 0.45);
dl.position.set(3, 6, 2);
scene.add(dl);

/* ── region R : star-shaped bean about RC ─────────────────────────────── */
const RC = { x: 1.0, y: 1.0 };
const TH0 = Math.PI * 1.25;                    // dent points toward origin
const rOf = th => 1.0 - 0.5 * Math.exp(-2 * (1 - Math.cos(th - TH0)));
const bPt = th => ({ x: RC.x + rOf(th) * Math.cos(th), y: RC.y + rOf(th) * Math.sin(th) });
function insideR(x, y) {
  const dx = x - RC.x, dy = y - RC.y, r = Math.hypot(dx, dy);
  if (r < 1e-9) return true;
  return r <= rOf(Math.atan2(dy, dx));
}
function clampToR(x, y) {
  const dx = x - RC.x, dy = y - RC.y, th = Math.atan2(dy, dx), r = Math.hypot(dx, dy);
  const rm = rOf(th) * 0.95;
  if (r <= rm) return { x, y };
  return { x: RC.x + rm * Math.cos(th), y: RC.y + rm * Math.sin(th) };
}
const bb = { x0: 1e9, x1: -1e9, y0: 1e9, y1: -1e9 };
for (let k = 0; k < 720; k++) {
  const p = bPt(k * Math.PI / 360);
  bb.x0 = Math.min(bb.x0, p.x); bb.x1 = Math.max(bb.x1, p.x);
  bb.y0 = Math.min(bb.y0, p.y); bb.y1 = Math.max(bb.y1, p.y);
}
const R_SPAN = Math.max(bb.x1 - bb.x0, bb.y1 - bb.y0);

/* ── state ────────────────────────────────────────────────────────────── */
let currentF = compileExpr('2 - 0.25*x*x - 0.25*y*y', ['x', 'y']);
function F(x, y) { let v; try { v = currentF(x, y); } catch (e) { v = NaN; } return Number.isFinite(v) ? v : 0; }
let nPart = 6;
let allMode = false;
const sample = { x: 1.15, y: 1.02 };
let riemann = 0;
const cellSize = () => R_SPAN / nPart;

/* ── grid-mesh helper ─────────────────────────────────────────────────── */
function makeGridGeom(nu, nv) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array((nu + 1) * (nv + 1) * 3), 3));
  const idx = [];
  for (let i = 0; i < nu; i++) for (let j = 0; j < nv; j++) {
    const a = i * (nv + 1) + j, b = a + 1, c = a + nv + 1, e = c + 1;
    idx.push(a, c, b, b, c, e);
  }
  g.setIndex(idx);
  return g;
}

/* ── xy-plane patch ───────────────────────────────────────────────────── */
const P0 = -1.35, P1 = 2.45;
const planeGeom = new THREE.PlaneGeometry(P1 - P0, P1 - P0);
planeGeom.rotateX(-Math.PI / 2);
const planeMesh = new THREE.Mesh(planeGeom, new THREE.MeshBasicMaterial({
  color: 0xe8e8e8, transparent: true, opacity: 0.55, depthWrite: false, side: THREE.DoubleSide
}));
planeMesh.position.set((P0 + P1) / 2, 0, (P0 + P1) / 2);
planeMesh.renderOrder = 0;
scene.add(planeMesh);
const bord = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints([
  W(P0, P0, 0), W(P1, P0, 0), W(P1, P1, 0), W(P0, P1, 0)
]), new THREE.LineBasicMaterial({ color: 0xc4c4c4 }));
bord.renderOrder = 1; scene.add(bord);

/* ── region fill + outline ────────────────────────────────────────────── */
const NR = 18, NTH = 128;
const regionGeom = makeGridGeom(NR, NTH);
(function fillRegion() {
  const pos = regionGeom.attributes.position; let k = 0;
  for (let i = 0; i <= NR; i++) {
    const s = i / NR;
    for (let j = 0; j <= NTH; j++) {
      const th = 2 * Math.PI * j / NTH, r = rOf(th) * s;
      pos.setXYZ(k++, RC.y + r * Math.sin(th), 0.007, RC.x + r * Math.cos(th));
    }
  }
  pos.needsUpdate = true; regionGeom.computeVertexNormals();
})();
const regionMesh = new THREE.Mesh(regionGeom, new THREE.MeshBasicMaterial({
  color: 0xbfe0dc, transparent: true, opacity: 0.5, depthWrite: false, side: THREE.DoubleSide
}));
regionMesh.renderOrder = 2; scene.add(regionMesh);

const bpts = [];
for (let j = 0; j < 256; j++) { const p = bPt(2 * Math.PI * j / 256); bpts.push(W(p.x, p.y, 0.012)); }
const bCurve = new THREE.CatmullRomCurve3(bpts, true);
const outline = new THREE.Mesh(new THREE.TubeGeometry(bCurve, 320, 0.023, 8, true),
  new THREE.MeshBasicMaterial({ color: 0x00a887 }));
outline.renderOrder = 4; scene.add(outline);

/* ── partition grid lines clipped to R ────────────────────────────────── */
const gridMat = new THREE.LineBasicMaterial({ color: 0x9aa5a5, transparent: true, opacity: 0.95 });
let gridLines = new THREE.LineSegments(new THREE.BufferGeometry(), gridMat);
gridLines.renderOrder = 3; scene.add(gridLines);
function marchLine(param, out) {
  const N = 200; let prev = null;
  for (let i = 0; i <= N; i++) {
    const p = param(i / N), ins = insideR(p.x, p.y);
    if (ins && prev) { out.push(W(prev.x, prev.y, 0.013), W(p.x, p.y, 0.013)); }
    prev = ins ? p : null;
  }
}
function buildGridLines() {
  const cs = cellSize(), pts = [];
  const kx = Math.ceil((bb.x1 - bb.x0) / cs), ky = Math.ceil((bb.y1 - bb.y0) / cs);
  for (let k = 0; k <= kx; k++) {
    const x = bb.x0 + k * cs;
    marchLine(t => ({ x, y: bb.y0 + t * (bb.y1 - bb.y0) }), pts);
  }
  for (let k = 0; k <= ky; k++) {
    const y = bb.y0 + k * cs;
    marchLine(t => ({ x: bb.x0 + t * (bb.x1 - bb.x0), y }), pts);
  }
  const old = gridLines.geometry;
  gridLines.geometry = new THREE.BufferGeometry().setFromPoints(pts);
  old.dispose();
}

/* ── surface z = f(x,y) ───────────────────────────────────────────────── */
const SN = 56, SX0 = -1.3, SX1 = 2.15;
const surfGeom = makeGridGeom(SN, SN);
const surfMesh = new THREE.Mesh(surfGeom, new THREE.MeshPhongMaterial({
  color: 0x9ecfcb, transparent: true, opacity: 0.5, depthWrite: false,
  side: THREE.DoubleSide, shininess: 18, specular: 0x223333
}));
surfMesh.renderOrder = 20; scene.add(surfMesh);
function updateSurface() {
  const pos = surfGeom.attributes.position; let k = 0;
  for (let i = 0; i <= SN; i++) {
    const x = SX0 + (SX1 - SX0) * i / SN;
    for (let j = 0; j <= SN; j++) {
      const y = SX0 + (SX1 - SX0) * j / SN;
      pos.setXYZ(k++, y, F(x, y), x);
    }
  }
  pos.needsUpdate = true; surfGeom.computeVertexNormals(); surfGeom.computeBoundingSphere();
}

/* ── darker patch of surface over R ───────────────────────────────────── */
const patchGeom = makeGridGeom(NR, NTH);
const patchMesh = new THREE.Mesh(patchGeom, new THREE.MeshPhongMaterial({
  color: 0x5fa9a4, transparent: true, opacity: 0.62, depthWrite: false,
  side: THREE.DoubleSide, shininess: 12
}));
patchMesh.renderOrder = 21; scene.add(patchMesh);
function updatePatch() {
  const pos = patchGeom.attributes.position; let k = 0;
  for (let i = 0; i <= NR; i++) {
    const s = i / NR;
    for (let j = 0; j <= NTH; j++) {
      const th = 2 * Math.PI * j / NTH, r = rOf(th) * s;
      const x = RC.x + r * Math.cos(th), y = RC.y + r * Math.sin(th);
      pos.setXYZ(k++, y, F(x, y) + 0.004, x);
    }
  }
  pos.needsUpdate = true; patchGeom.computeVertexNormals(); patchGeom.computeBoundingSphere();
}

/* ── faint vertical cylinder wall ─────────────────────────────────────── */
const wallGeom = makeGridGeom(1, NTH);
const wallMesh = new THREE.Mesh(wallGeom, new THREE.MeshBasicMaterial({
  color: 0xd6dbda, transparent: true, opacity: 0.3, depthWrite: false, side: THREE.DoubleSide
}));
wallMesh.renderOrder = 5; scene.add(wallMesh);
function updateWall() {
  const pos = wallGeom.attributes.position; let k = 0;
  for (let i = 0; i <= 1; i++) {
    for (let j = 0; j <= NTH; j++) {
      const th = 2 * Math.PI * j / NTH, p = bPt(th);
      pos.setXYZ(k++, p.y, i === 0 ? 0 : F(p.x, p.y), p.x);
    }
  }
  pos.needsUpdate = true; wallGeom.computeVertexNormals(); wallGeom.computeBoundingSphere();
}

/* ── highlighted column + base rectangle ──────────────────────────────── */
const sideMat = new THREE.MeshPhongMaterial({
  color: 0xf5b06a, transparent: true, opacity: 0.55, depthWrite: false, side: THREE.DoubleSide, shininess: 8
});
const topMat = new THREE.MeshPhongMaterial({
  color: 0xe89a48, transparent: true, opacity: 0.85, depthWrite: false, side: THREE.DoubleSide, shininess: 8
});
const column = new THREE.Mesh(new THREE.BoxGeometry(1, 1, 1),
  [sideMat, sideMat, topMat, sideMat, sideMat, sideMat]);
column.renderOrder = 8; scene.add(column);

const baseGeom = new THREE.PlaneGeometry(1, 1); baseGeom.rotateX(-Math.PI / 2);
const baseRect = new THREE.Mesh(baseGeom, new THREE.MeshBasicMaterial({
  color: 0xe89a48, transparent: true, opacity: 0.85, depthWrite: false, side: THREE.DoubleSide
}));
baseRect.renderOrder = 9; scene.add(baseRect);

/* ── all columns (instanced) ──────────────────────────────────────────── */
const MAXI = 24 * 24;
const instMesh = new THREE.InstancedMesh(new THREE.BoxGeometry(1, 1, 1),
  new THREE.MeshPhongMaterial({
    color: 0xf5b06a, transparent: true, opacity: 0.35, depthWrite: false, side: THREE.DoubleSide, shininess: 6
  }), MAXI);
instMesh.renderOrder = 7; instMesh.count = 0; instMesh.visible = false;
instMesh.frustumCulled = false;
scene.add(instMesh);
const _m4 = new THREE.Matrix4(), _q = new THREE.Quaternion(),
  _pv = new THREE.Vector3(), _sv = new THREE.Vector3();

/* ── red dots + dashed segment ────────────────────────────────────────── */
const dotMat = new THREE.MeshBasicMaterial({ color: 0xe8372a });
const dotLow = new THREE.Mesh(new THREE.SphereGeometry(0.075, 20, 14), dotMat);
const dotHigh = new THREE.Mesh(new THREE.SphereGeometry(0.075, 20, 14), dotMat);
dotLow.renderOrder = 12; dotHigh.renderOrder = 12;
scene.add(dotLow, dotHigh);
const dashMat = new THREE.LineDashedMaterial({ color: 0xe8372a, dashSize: 0.12, gapSize: 0.10 });
const dashLine = new THREE.Line(new THREE.BufferGeometry().setFromPoints(
  [new THREE.Vector3(), new THREE.Vector3(0, 1, 0)]), dashMat);
dashLine.renderOrder = 12; scene.add(dashLine);

/* ── axes ─────────────────────────────────────────────────────────────── */
function axisArrow(dir, len) {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: 0x111111 });
  const shaft = new THREE.Mesh(new THREE.CylinderGeometry(0.017, 0.017, len - 0.22, 12), mat);
  shaft.position.set(0, (len - 0.22) / 2, 0);
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.075, 0.24, 18), mat);
  head.position.set(0, len - 0.11, 0);
  g.add(shaft, head);
  g.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
  g.renderOrder = 30;
  return g;
}
const AXY = 2.95, AZ = 3.15;
scene.add(axisArrow(new THREE.Vector3(0, 1, 0), AZ));   // math z (up)
scene.add(axisArrow(new THREE.Vector3(1, 0, 0), AXY));  // math y (right)
scene.add(axisArrow(new THREE.Vector3(0, 0, 1), AXY));  // math x (toward viewer)

/* ── leader arrows ────────────────────────────────────────────────────── */
function makeLeader() {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: 0x111111 });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(), new THREE.Vector3()]),
    new THREE.LineBasicMaterial({ color: 0x111111 }));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.055, 0.17, 14), mat);
  g.add(line, head);
  g.renderOrder = 30;
  g.userData.set = (a, b) => {
    const dir = b.clone().sub(a);
    const L = dir.length(); if (L < 1e-4) return;
    dir.divideScalar(L);
    const tip = b.clone().addScaledVector(dir, -0.02);
    const base = tip.clone().addScaledVector(dir, -0.17);
    line.geometry.setFromPoints([a, base]);
    line.geometry.attributes.position.needsUpdate = true;
    head.position.copy(base).addScaledVector(dir, 0.085);
    head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  };
  scene.add(g);
  return g;
}
const ldHeight = makeLeader(), ldVolume = makeLeader(), ldArea = makeLeader(), ldPoint = makeLeader();

// label anchors, given in math coords
const A_ZEQ = W(-0.65, 2.30, 2.95);
const A_HEIGHT = W(-0.30, 3.25, 1.95);
const A_VOLUME = W(0.60, 3.40, 0.35);
const A_AREA = W(2.45, -0.55, -0.55);
const A_POINT = W(2.70, 1.25, -0.62);

/* ── updates ──────────────────────────────────────────────────────────── */
function updateColumns() {
  const cs = cellSize();
  const i = Math.floor((sample.x - bb.x0) / cs), j = Math.floor((sample.y - bb.y0) / cs);
  const cx = bb.x0 + (i + 0.5) * cs, cy = bb.y0 + (j + 0.5) * cs;
  const h = F(sample.x, sample.y);

  column.position.set(cy, h / 2, cx);
  column.scale.set(cs, Math.max(Math.abs(h), 1e-3), cs);
  baseRect.position.set(cy, 0.016, cx);
  baseRect.scale.set(cs, cs, 1);

  dotLow.position.set(sample.y, 0.035, sample.x);
  dotHigh.position.set(sample.y, h, sample.x);
  dashLine.geometry.setFromPoints([
    new THREE.Vector3(sample.y, 0.035, sample.x),
    new THREE.Vector3(sample.y, h, sample.x)]);
  dashLine.geometry.attributes.position.needsUpdate = true;
  dashLine.computeLineDistances();

  // full Riemann sum + instanced columns
  const kx = Math.ceil((bb.x1 - bb.x0) / cs), ky = Math.ceil((bb.y1 - bb.y0) / cs);
  let sum = 0, cnt = 0;
  for (let a = 0; a < kx; a++) for (let b = 0; b < ky; b++) {
    const px = bb.x0 + (a + 0.5) * cs, py = bb.y0 + (b + 0.5) * cs;
    if (!insideR(px, py)) continue;
    const hh = F(px, py);
    sum += hh * cs * cs;
    if (allMode && cnt < MAXI) {
      _pv.set(py, hh / 2, px);
      _sv.set(cs * 0.94, Math.max(Math.abs(hh), 1e-3), cs * 0.94);
      _m4.compose(_pv, _q, _sv);
      instMesh.setMatrixAt(cnt, _m4);
      cnt++;
    }
  }
  riemann = sum;
  instMesh.count = allMode ? cnt : 0;
  instMesh.visible = allMode;
  instMesh.instanceMatrix.needsUpdate = true;

  // leaders
  ldHeight.userData.set(A_HEIGHT, new THREE.Vector3(sample.y + 0.06, h * 0.52, sample.x));
  ldVolume.userData.set(A_VOLUME, new THREE.Vector3(cy + cs * 0.5, h * 0.62, cx));
  ldArea.userData.set(A_AREA, new THREE.Vector3(cy - cs * 0.35, 0.03, cx + cs * 0.5));
  ldPoint.userData.set(A_POINT, new THREE.Vector3(sample.y, 0.05, sample.x + 0.10));
}

function updateReadout() {
  const cs = cellSize(), dA = cs * cs, h = F(sample.x, sample.y);
  document.getElementById('readout').innerHTML =
    `x*<sub>k</sub> = ${sample.x.toFixed(2)} &nbsp; y*<sub>k</sub> = ${sample.y.toFixed(2)}<br>` +
    `f(x*<sub>k</sub>, y*<sub>k</sub>) = ${h.toFixed(3)}<br>` +
    `&Delta;A<sub>k</sub> = ${dA.toFixed(4)}<br>` +
    `f&middot;&Delta;A<sub>k</sub> = <b>${(h * dA).toFixed(4)}</b><br>` +
    (allMode
      ? `&Sigma; f&Delta;A<sub>k</sub> = <b>${riemann.toFixed(4)}</b> (${instMesh.count} cols)`
      : `&Sigma; f&Delta;A<sub>k</sub> = ${riemann.toFixed(4)}`);
}

function updateAll() {
  updateSurface(); updatePatch(); updateWall(); updateColumns(); updateReadout();
}

