  title: 'Approximating parallelepiped',
  tooltip: 'Column of volume f(x*,y*)·ΔA',
  body: 'Its base is one subrectangle of area ΔA_k inside R and its height is the value f(x*_k, y*_k) of the integrand at the sample point, so its volume is f(x*_k, y*_k)·ΔA_k — one term of the Riemann sum.'
});
registerInteractive(surfMesh, {
  title: 'The surface z = f(x, y)',
  tooltip: 'The graph of the integrand',
  body: 'Every column reaches up to this surface. The double integral of f over R is the limit of the sums of the column volumes, i.e. the volume of the solid between R and this surface.'
});
registerInteractive(regionMesh, {
  title: 'Region R with its partition',
  tooltip: 'Region R, partitioned into subrectangles',
  body: 'R is cut by a rectangular grid; each subrectangle lying in R carries one column. Refining the grid shrinks every ΔA_k.'
});

/* ── drag the sample point ────────────────────────────────────────────── */
const dom = renderer.domElement;
const dragRay = new THREE.Raycaster();
const dragPlane = new THREE.Plane(new THREE.Vector3(0, 1, 0), 0);
const ndc = new THREE.Vector2();
const hitPt = new THREE.Vector3();
let dragging = false;
let sampleTween = null;

function planeHit(ev) {
  const r = dom.getBoundingClientRect();
  ndc.x = ((ev.clientX - r.left) / r.width) * 2 - 1;
  ndc.y = -((ev.clientY - r.top) / r.height) * 2 + 1;
  dragRay.setFromCamera(ndc, camera);
  return dragRay.ray.intersectPlane(dragPlane, hitPt) ? hitPt : null;
}
dom.addEventListener('pointerdown', (ev) => {
  const p = planeHit(ev);
  if (!p) return;
  if (Math.hypot(p.z - sample.x, p.x - sample.y) < 0.38) {
    dragging = true; sampleTween = null; controls.enabled = false;
    dom.setPointerCapture?.(ev.pointerId);
  }
});
dom.addEventListener('pointermove', (ev) => {
  if (!dragging) return;
  const p = planeHit(ev);
  if (!p) return;
  const c = clampToR(p.z, p.x);
  sample.x = c.x; sample.y = c.y;
  updateColumns(); updateReadout();
});
const endDrag = () => { if (dragging) { dragging = false; controls.enabled = true; } };
window.addEventListener('pointerup', endDrag);
window.addEventListener('pointercancel', endDrag);

/* ── controls wiring ──────────────────────────────────────────────────── */
const nSlider = document.getElementById('nSlider');
const nVal = document.getElementById('nVal');
nSlider.addEventListener('input', () => {
  nPart = parseInt(nSlider.value, 10);
  nVal.textContent = nPart;
  buildGridLines(); updateColumns(); updateReadout();
});
const btnSingle = document.getElementById('btnSingle');
const btnAll = document.getElementById('btnAll');
function setMode(all) {
  allMode = all;
  btnSingle.classList.toggle('active', !all);
  btnAll.classList.toggle('active', all);
  updateColumns(); updateReadout();
}
btnSingle.addEventListener('click', () => setMode(false));
btnAll.addEventListener('click', () => setMode(true));

/* ── sample-point tween (used by the guided demo) ─────────────────────── */
function tweenSample(tx, ty, dur = 900) {
  sampleTween = { x0: sample.x, y0: sample.y, x1: tx, y1: ty, t0: performance.now(), dur };
}
(function tick() {
  requestAnimationFrame(tick);
  if (!sampleTween) return;
  const k = Math.min(1, (performance.now() - sampleTween.t0) / sampleTween.dur);
  const e = k < 0.5 ? 2 * k * k : 1 - Math.pow(-2 * k + 2, 2) / 2;
  sample.x = sampleTween.x0 + (sampleTween.x1 - sampleTween.x0) * e;
  sample.y = sampleTween.y0 + (sampleTween.y1 - sampleTween.y0) * e;
  updateColumns(); updateReadout();
  if (k >= 1) sampleTween = null;
})();

/* ── guided demo ──────────────────────────────────────────────────────── */
const STEPS = [
  {
    t: 'One representative column',
    n: 'A single subrectangle of area ΔA_k in the base region carries a column whose top just touches the surface at height f(x*_k, y*_k); its volume is f(x*_k, y*_k)·ΔA_k.',
    all: false, part: 6, s: [1.32, 1.22]
  },
  {
    t: 'Move the sample point',
    n: 'The red dot moves across R: the column follows and its height reads off the surface directly above, so the height depends only on where the sample point is. Try dragging it yourself.',
    all: false, part: 6, s: [0.55, 1.85]
  },
  {
    t: 'Change the integrand',
    n: 'Edit f(x, y) in the box above (try 2 + 0.4*sin(1.4*x)*cos(1.4*y)). The teal surface redraws and every column height — including the highlighted one — is rebuilt from the new formula.',
    all: false, part: 6, s: [1.32, 1.22]
  },
  {
    t: 'The whole Riemann sum',
    n: 'All columns: the sum Σ f(x*_k, y*_k)ΔA_k of the parallelepiped volumes approximates the solid between R and the surface.',
    all: true, part: 8, s: [1.32, 1.22]
  },
  {
    t: 'Refine the partition',
    n: 'Increasing n shrinks each ΔA_k; the staircase of columns closes in on the smooth solid, and the Riemann sum tends to the double integral.',
    all: true, part: 20, s: [1.32, 1.22]
  }
];
let stepIdx = 0;
function goToStep(i) {
  stepIdx = (i + STEPS.length) % STEPS.length;
  const st = STEPS[stepIdx];
  nPart = st.part; nSlider.value = st.part; nVal.textContent = st.part;
  buildGridLines();
  setMode(st.all);
  tweenSample(st.s[0], st.s[1], 900);
  document.getElementById('stepTitle').textContent = (stepIdx + 1) + '. ' + st.t;
  document.getElementById('stepText').textContent = st.n;
}
document.getElementById('btnPrev').addEventListener('click', () => goToStep(stepIdx - 1));
document.getElementById('btnNext').addEventListener('click', () => goToStep(stepIdx + 1));
goToStep(0);

document.getElementById('btnReset').style.display = '';
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
