// @FIGURE_CODE_BEGIN
/* ── Element spec (built exactly as listed) ───────────────────────────────
   axes x,y,z     -> CylinderGeometry shaft + ConeGeometry head, black #111
   xy-plane patch -> PlaneGeometry #e8e8e8 a=.55 + LineLoop border #c4c4c4
   region R fill  -> radial BufferGeometry (bean, concave dent) z=.008 #bfe0dc a=.48
   region outline -> TubeGeometry r=.030 along boundary, #00a887
   grid partition -> LineSegments, clipped to R, #9aa5a5
   surface        -> 64x64 BufferGeometry graph of f, MeshPhong #9ecfcb a=.45
   patch over R   -> radial BufferGeometry at z=f, #6fb3ae a=.52
   cylinder wall  -> 1 x 192 strip BufferGeometry, #e0e0e0 a=.45
   column         -> BoxGeometry, sides #f7b96f a=.72, top #e8983f a=.97
   base rect      -> PlaneGeometry #e89a48 a=.92
   all columns    -> InstancedMesh(BoxGeometry) #f7b96f a=.42
   red dots       -> SphereGeometry(0.095) #e8372a, depthTest off  (x2)
   dashed segment -> pool of CylinderGeometry dashes r=.032 #e8372a, depthTest off
   leader arrows  -> Line + ConeGeometry head, #111, depthTest off
──────────────────────────────────────────────────────────────────────────*/

// math (x,y,z)  ->  world (X = y, Y = z, Z = x)      [world is Y-up]
const W = (x, y, z) => new THREE.Vector3(y, z, x);

/* ── lights ───────────────────────────────────────────────────────────── */
scene.add(new THREE.AmbientLight(0xffffff, 0.95));
const dl = new THREE.DirectionalLight(0xffffff, 0.40);
dl.position.set(3, 7, 2);
scene.add(dl);

/* ── region R : bean with a real concave dent facing the origin ───────── */
const RC = { x: 1.25, y: 1.25 };
const TH0 = Math.PI * 1.25;                 // dent points back toward the origin
const rOf = th => {
  const u = th - TH0;
  return 1.55 + 0.18 * Math.cos(2 * u) - 0.95 * Math.exp(-2.6 * (1 - Math.cos(u)));
};
const bPt = th => ({ x: RC.x + rOf(th) * Math.cos(th), y: RC.y + rOf(th) * Math.sin(th) });
function insideR(x, y) {
  const dx = x - RC.x, dy = y - RC.y, r = Math.hypot(dx, dy);
  if (r < 1e-9) return true;
  return r <= rOf(Math.atan2(dy, dx));
}
function clampToR(x, y) {
  const dx = x - RC.x, dy = y - RC.y, th = Math.atan2(dy, dx), r = Math.hypot(dx, dy);
  const rm = rOf(th) * 0.90;
  if (r <= rm) return { x, y };
  return { x: RC.x + rm * Math.cos(th), y: RC.y + rm * Math.sin(th) };
}
const bb = { x0: 1e9, x1: -1e9, y0: 1e9, y1: -1e9 };
for (let k = 0; k < 1440; k++) {
  const p = bPt(k * Math.PI / 720);
  bb.x0 = Math.min(bb.x0, p.x); bb.x1 = Math.max(bb.x1, p.x);
  bb.y0 = Math.min(bb.y0, p.y); bb.y1 = Math.max(bb.y1, p.y);
}
const R_SPAN = Math.max(bb.x1 - bb.x0, bb.y1 - bb.y0);

/* ── state ────────────────────────────────────────────────────────────── */
const DEF_F = '2.3 + 0.4*sin(1.1*x) - 0.35*cos(1.0*y)';
let currentF = compileExpr(DEF_F, ['x', 'y']);
function F(x, y) { let v; try { v = currentF(x, y); } catch (e) { v = NaN; } return Number.isFinite(v) ? v : 0; }
let nPart = 6;
let allMode = false;
const sample = { x: 1.40, y: 1.15 };
let riemann = 0;
const cellSize = () => R_SPAN / nPart;

/* ── grid-mesh helper ─────────────────────────────────────────────────── */
function makeGridGeom(nu, nv) {
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array((nu + 1) * (nv + 1) * 3), 3));
  const idx = [];
  for (let i = 0; i < nu; i++) for (let j = 0; j < nv; j++) {
    const a = i * (nv + 1) + j, b = a + 1, c = a + nv + 1, e = c + 1;
    idx.push(a, c, b, b, c, e);
  }
  g.setIndex(idx);
  return g;
}

/* ── xy-plane patch ───────────────────────────────────────────────────── */
const P0 = -1.25, P1 = 3.95;
const planeGeom = new THREE.PlaneGeometry(P1 - P0, P1 - P0);
planeGeom.rotateX(-Math.PI / 2);
const planeMesh = new THREE.Mesh(planeGeom, new THREE.MeshBasicMaterial({
  color: 0xe8e8e8, transparent: true, opacity: 0.55, depthWrite: false, side: THREE.DoubleSide
}));
planeMesh.position.set((P0 + P1) / 2, 0, (P0 + P1) / 2);
planeMesh.renderOrder = 0;
scene.add(planeMesh);
const bord = new THREE.LineLoop(new THREE.BufferGeometry().setFromPoints([
  W(P0, P0, 0), W(P1, P0, 0), W(P1, P1, 0), W(P0, P1, 0)
]), new THREE.LineBasicMaterial({ color: 0xc4c4c4 }));
bord.renderOrder = 1; scene.add(bord);

/* ── region fill + outline ────────────────────────────────────────────── */
const NR = 20, NTH = 192;
const regionGeom = makeGridGeom(NR, NTH);
(function fillRegion() {
  const pos = regionGeom.attributes.position; let k = 0;
  for (let i = 0; i <= NR; i++) {
    const s = i / NR;
    for (let j = 0; j <= NTH; j++) {
      const th = 2 * Math.PI * j / NTH, r = rOf(th) * s;
      pos.setXYZ(k++, RC.y + r * Math.sin(th), 0.008, RC.x + r * Math.cos(th));
    }
  }
  pos.needsUpdate = true; regionGeom.computeVertexNormals();
})();
const regionMesh = new THREE.Mesh(regionGeom, new THREE.MeshBasicMaterial({
  color: 0xbfe0dc, transparent: true, opacity: 0.48, depthWrite: false, side: THREE.DoubleSide
