function marchLine(param, out) {
  const N = 240; let prev = null;
  for (let i = 0; i <= N; i++) {
    const p = param(i / N), ins = insideR(p.x, p.y);
    if (ins && prev) out.push(W(prev.x, prev.y, 0.015), W(p.x, p.y, 0.015));
