function updateDashes(mx, my, z0, z1) {
  const dash = 0.15, gap = 0.11, per = dash + gap;
  let n = 0, t = z0;
  while (t < z1 - 1e-6 && n < DASH_MAX) {
    const seg = Math.min(dash, z1 - t);
    const m = dashPool[n++];
    m.visible = true;
    m.position.set(my, t + seg / 2, mx);
    m.scale.set(1, seg, 1);
    t += per;
  }
  for (let i = n; i < DASH_MAX; i++) dashPool[i].visible = false;
