function makeLeader() {
  const g = new THREE.Group();
  const mat = new THREE.MeshBasicMaterial({ color: 0x111111, depthTest: false });
  const line = new THREE.Line(new THREE.BufferGeometry().setFromPoints(
    [new THREE.Vector3(), new THREE.Vector3()]),
    new THREE.LineBasicMaterial({ color: 0x111111, depthTest: false }));
  const head = new THREE.Mesh(new THREE.ConeGeometry(0.068, 0.21, 14), mat);
  g.add(line, head);
  g.renderOrder = 45;
  g.userData.set = (a, b) => {
    const dir = b.clone().sub(a);
    const L = dir.length(); if (L < 1e-4) return;
    dir.divideScalar(L);
    const tip = b.clone().addScaledVector(dir, -0.02);
    const base = tip.clone().addScaledVector(dir, -0.21);
    line.geometry.setFromPoints([a, base]);
    line.geometry.attributes.position.needsUpdate = true;
    head.position.copy(base).addScaledVector(dir, 0.105);
    head.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir);
  };
  scene.add(g);
  return g;
}
