function updateColumns() {
  const cs = cellSize();
  const i = Math.floor((sample.x - bb.x0) / cs), j = Math.floor((sample.y - bb.y0) / cs);
  const cx = bb.x0 + (i + 0.5) * cs, cy = bb.y0 + (j + 0.5) * cs;
  const h = F(sample.x, sample.y);

  column.position.set(cy, h / 2, cx);
  column.scale.set(cs * 0.98, Math.max(Math.abs(h), 1e-3), cs * 0.98);
  baseRect.position.set(cy, 0.020, cx);
  baseRect.scale.set(cs * 0.98, cs * 0.98, 1);

  dotLow.position.set(sample.y, 0.05, sample.x);
  dotHigh.position.set(sample.y, h, sample.x);
  updateDashes(sample.x, sample.y, 0.06, Math.max(h - 0.03, 0.08));

  // full Riemann sum (+ instanced columns when shown)
  const kx = Math.ceil((bb.x1 - bb.x0) / cs), ky = Math.ceil((bb.y1 - bb.y0) / cs);
  let sum = 0, cnt = 0;
  for (let a = 0; a < kx; a++) for (let b = 0; b < ky; b++) {
    const px = bb.x0 + (a + 0.5) * cs, py = bb.y0 + (b + 0.5) * cs;
    if (!insideR(px, py)) continue;
    const hh = F(px, py);
    sum += hh * cs * cs;
    if (allMode && cnt < MAXI) {
      _pv.set(py, hh / 2, px);
      _sv.set(cs * 0.94, Math.max(Math.abs(hh), 1e-3), cs * 0.94);
      _m4.compose(_pv, _q, _sv);
      instMesh.setMatrixAt(cnt, _m4);
      cnt++;
    }
  }
  riemann = sum;
  instMesh.count = allMode ? cnt : 0;
  instMesh.visible = allMode;
  instMesh.instanceMatrix.needsUpdate = true;

  // leaders: same directions as the source figure
  ldHeight.userData.set(A_HEIGHT, W(sample.x, sample.y + 0.06, h * 0.55));
  ldVolume.userData.set(A_VOLUME, W(cx, cy + cs * 0.52, h * 0.45));
  ldArea.userData.set(A_AREA, W(cx + cs * 0.45, cy - cs * 0.30, 0.03));
  ldPoint.userData.set(A_POINT, W(sample.x + 0.06, sample.y + 0.02, 0.07));
}

